pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(0));
        amount = bound(amount, 1, 100 ether);

        vm.deal(address(c), amount);

        uint256 balanceBefore = recipient.balance;

        vm.prank(address(this));
        c.withdrawAll(recipient);

        uint256 balanceAfter = recipient.balance;

        assertTrue(balanceAfter > balanceBefore);
    }
}

